1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	
6	  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
7	
8	  return Buffer.concat(chunks).toString("utf8");
9	};
10	
11	const scenario = JSON.parse(await readStdin()) as Scenario;
12	
13	process.stdout.write(JSON.stringify(runScenario(scenario)));
14

1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  policy: number;
21	  incident: {
22	    cause: string;
23	    damages: Damage[];
24	  };
25	};
26	
27	export type Step = QuoteStep | ClaimStep;
28	
29	export type Customer = {
30	  yearsWithMHPCO: number;
31	};
32	
33	export type Scenario = {
34	  customer: Customer;
35	  steps: Step[];
36	};
37	
38	export type ScenarioResults = {
39	  results: unknown[];
40	};
41	
42	const sum = (amounts: number[]): number =>
43	  amounts.reduce((total, amount) => total + amount, 0);
44	
45	const PROCESSING_FEE = 5;
46	
47	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
48	// 115.00000000000001); snap to cent precision so only genuine fractions round.
49	const atCentPrecision = (amount: number): number => Number(amount.toFixed(6));
50	
51	// The office rounds every amount its own way: premiums it collects go up,
52	// payouts it hands out go down.
53	const roundUpInMHPCOsFavour = (amount: number): number =>
54	  Math.ceil(atCentPrecision(amount));
55	
56	const roundDownInMHPCOsFavour = (amount: number): number =>
57	  Math.floor(atCentPrecision(amount));
58	
59	// One entry per insurable type: every fact the office knows about a type lives
60	// here, so adding a type is a single edit.
61	type ItemKind = {
62	  basePremium: number;
63	  insuranceValue: number;
64	  isComponent: boolean;
65	};
66	
67	const ITEM_CATALOGUE: Record<string, ItemKind> = {
68	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
69	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
70	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
71	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
72	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
73	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
74	};
75	
76	const kindOf = (item: Item): ItemKind => {
77	  const kind = ITEM_CATALOGUE[item.type];
78	
79	  if (!kind) throw new Error(`The MHPCO does not insure "${item.type}" items.`);
80	
81	  return kind;
82	};
83	
84	const basePremiumOf = (item: Item): number => kindOf(item).basePremium;
85	
86	const insuranceValueOf = (item: Item): number => kindOf(item).insuranceValue;
87	
88	const isComponentOf = (item: Item): boolean => kindOf(item).isComponent;
89	
90	const BLOCK_SIZE = 3;
91	const BLOCK_BASE_PREMIUM = 60;
92	
93	const groupByType = (items: Item[]): Item[][] => {
94	  const itemsByType = new Map<string, Item[]>();
95	
96	  for (const item of items) {
97	    const sameTypeItems = itemsByType.get(item.type);
98	    if (sameTypeItems) sameTypeItems.push(item);
99	    else itemsByType.set(item.type, [item]);
100	  }
101	
102	  return [...itemsByType.values()];
103	};
104	
105	// A block is a special price for exactly 3 alike components; any other count,
106	// and any main item, is charged per item. Groups come from groupByType, which
107	// only ever emits non-empty ones, so the first item stands for the whole group.
108	const sameTypeBasePremiumOf = (sameTypeItems: Item[]): number =>
109	  sameTypeItems.length === BLOCK_SIZE && isComponentOf(sameTypeItems[0])
110	    ? BLOCK_BASE_PREMIUM
111	    : sum(sameTypeItems.map(basePremiumOf));
112	
113	const policyBasePremiumOf = (items: Item[]): number =>
114	  sum(groupByType(items).map(sameTypeBasePremiumOf));
115	
116	// Both rate tables stack the same way: every rule whose condition holds
117	// contributes its signed rate, and the rates add. Discounts carry a negative
118	// rate so a table sums without sign-juggling at the call site.
119	type RateRule<Subject> = {
120	  appliesTo: (subject: Subject) => boolean;
121	  rate: number;
122	};
123	
124	const totalRateOf = <Subject>(
125	  rules: RateRule<Subject>[],
126	  subject: Subject,
127	): number =>
128	  sum(
129	    rules.filter(({ appliesTo }) => appliesTo(subject)).map(({ rate }) => rate),
130	  );
131	
132	const HIGH_ENCHANTMENT_THRESHOLD = 5;
133	
134	const isCursed = (item: Item): boolean => item.cursed === true;
135	
136	const isHighlyEnchanted = (item: Item): boolean =>
137	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
138	
139	const ITEM_SURCHARGES: RateRule<Item>[] = [
140	  { appliesTo: isCursed, rate: 0.5 },
141	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
142	];
143	
144	const itemSurchargeRateOf = (item: Item): number =>
145	  totalRateOf(ITEM_SURCHARGES, item);
146	
147	// Item-specific surcharges are charged on that item's own base premium, not on
148	// the policy total.
149	const itemSurchargesOf = (item: Item): number =>
150	  basePremiumOf(item) * itemSurchargeRateOf(item);
151	
152	// Everything outside the item list that a policy-wide modifier may depend on:
153	// who is asking, and where this quote sits in their history with the office.
154	type QuoteContext = {
155	  customer: Customer;
156	  precedingQuotes: number;
157	};
158	
159	const LOYALTY_YEARS_THRESHOLD = 2;
160	
161	const isLoyal = ({ customer }: QuoteContext): boolean =>
162	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
163	
164	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
165	  precedingQuotes > 0;
166	
167	const alwaysApplies = (): boolean => true;
168	
169	const POLICY_MODIFIERS: RateRule<QuoteContext>[] = [
170	  { appliesTo: alwaysApplies, rate: 0.1 }, // first insurance surcharge
171	  { appliesTo: isLoyal, rate: -0.2 },
172	  { appliesTo: isFollowUpContract, rate: -0.15 },
173	];
174	
175	// Policy-wide modifiers are charged on the base premium alone, never on base +
176	// item surcharges: a cursed sword quotes at 100 + 50 + 10 + 5 = 165, where the
177	// 10 is 10 % of 100 rather than of 150.
178	const policyModifierRateOf = (context: QuoteContext): number =>
179	  totalRateOf(POLICY_MODIFIERS, context);
180	
181	const quote = (step: QuoteStep, context: QuoteContext): number => {
182	  const policyBasePremium = policyBasePremiumOf(step.items);
183	  const itemSurcharges = sum(step.items.map(itemSurchargesOf));
184	  const policyModifiers = policyBasePremium * policyModifierRateOf(context);
185	
186	  return roundUpInMHPCOsFavour(
187	    policyBasePremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
188	  );
189	};
190	
191	const DEDUCTIBLE_PER_DAMAGE = 100;
192	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
193	
194	const insuranceSumOf = (items: Item[]): number =>
195	  sum(items.map(insuranceValueOf));
196	
197	const REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
198	const REDUCED_REIMBURSEMENT_SHARE = 0.5;
199	
200	// Heavily enchanted items are notoriously hard to appraise, so the office only
201	// reimburses half of the damage before applying the deductible.
202	const reimbursementShareOf = (item: Item): number =>
203	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
204	    ? REDUCED_REIMBURSEMENT_SHARE
205	    : 1;
206	
207	const rejectImpossibleDamage = (damage: Damage): void => {
208	  if (damage.amount < 0) {
209	    throw new Error(
210	      `A damage cannot be worth less than nothing, but ${damage.amount} G was claimed for a "${damage.itemType}".`,
211	    );
212	  }
213	};
214	
215	const payoutForDamage = (damage: Damage, damagedItem: Item): number => {
216	  rejectImpossibleDamage(damage);
217	
218	  return (
219	    damage.amount * reimbursementShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE
220	  );
221	};
222	
223	// A claim points at the quote step that issued its policy. Every scenario under
224	// test points at a real quote; rejecting a dangling or non-quote reference is a
225	// deferred validation test, so this narrows without complaining for now.
226	const policyOf = (scenario: Scenario, step: ClaimStep): QuoteStep =>
227	  scenario.steps[step.policy] as QuoteStep;
228	
229	// A damage names the type it hit; the clauses that shape its payout live on the
230	// insured item itself. Each damage claims one distinct insured item, so a policy
231	// covering one sword cannot absorb two sword damages: the items are handed out
232	// one at a time and never handed out twice. Both rejections fall out of that one
233	// mechanism — an uncovered type never matches, an over-claim finds none left.
234	type ClaimedDamage = { damage: Damage; damagedItem: Item };
235	
236	const matchDamagesToInsuredItems = (
237	  damages: Damage[],
238	  insuredItems: Item[],
239	): ClaimedDamage[] => {
240	  const unclaimedItems = [...insuredItems];
241	
242	  return damages.map((damage) => {
243	    const damagedItemIndex = unclaimedItems.findIndex(
244	      (item) => item.type === damage.itemType,
245	    );
246	
247	    if (damagedItemIndex === -1) {
248	      throw new Error(
249	        `The policy does not cover a "${damage.itemType}" that is still unclaimed in this incident.`,
250	      );
251	    }
252	
253	    return { damage, damagedItem: unclaimedItems.splice(damagedItemIndex, 1)[0] };
254	  });
255	};
256	
257	const claim = (step: ClaimStep, policy: QuoteStep, remainingCap: number) => {
258	  const claimedDamages = matchDamagesToInsuredItems(
259	    step.incident.damages,
260	    policy.items,
261	  );
262	  const desiredPayout = roundDownInMHPCOsFavour(
263	    sum(
264	      claimedDamages.map(({ damage, damagedItem }) =>
265	        payoutForDamage(damage, damagedItem),
266	      ),
267	    ),
268	  );
269	  const payout = Math.min(desiredPayout, remainingCap);
270	
271	  return { payout, remainingCap: remainingCap - payout };
272	};
273	
274	const capOf = (policy: QuoteStep): number =>
275	  insuranceSumOf(policy.items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
276	
277	// A policy's cap is consumed by every claim against it, so what is left has to
278	// survive from one step to the next. The ledger owns that carrying-over: it
279	// starts a policy at its full cap on first sight, and remembers each drawdown.
280	const createCapLedger = () => {
281	  const remainingCapByPolicy = new Map<number, number>();
282	
283	  return {
284	    remainingCapFor: (policyIndex: number, policy: QuoteStep): number =>
285	      remainingCapByPolicy.get(policyIndex) ?? capOf(policy),
286	    recordDrawdown: (policyIndex: number, remainingCap: number): void => {
287	      remainingCapByPolicy.set(policyIndex, remainingCap);
288	    },
289	  };
290	};
291	
292	export const runScenario = (scenario: Scenario): ScenarioResults => {
293	  const capLedger = createCapLedger();
294	
295	  const settleClaim = (step: ClaimStep) => {
296	    const policy = policyOf(scenario, step);
297	    const result = claim(
298	      step,
299	      policy,
300	      capLedger.remainingCapFor(step.policy, policy),
301	    );
302	
303	    capLedger.recordDrawdown(step.policy, result.remainingCap);
304	
305	    return result;
306	  };
307	
308	  // Steps, not quotes: with only quote-then-claim scenarios under test the two
309	  // counts agree. A claim before a quote would make them diverge, and that is
310	  // the deferred test's job to pin down.
311	  const issueQuote = (step: QuoteStep, precedingSteps: number) => ({
312	    premium: quote(step, {
313	      customer: scenario.customer,
314	      precedingQuotes: precedingSteps,
315	    }),
316	  });
317	
318	  return {
319	    results: scenario.steps.map((step, precedingSteps) =>
320	      step.op === "claim" ? settleClaim(step) : issueQuote(step, precedingSteps),
321	    ),
322	  };
323	};
